package mx.com.mesaregia.logistica.application.service.impl; import mx.com.mesaregia.logistica.api.response.MisOperacionResponse; import mx.com.mesaregia.logistica.application.service.AsignacionLogisticaQueryService; import mx.com.mesaregia.logistica.domain.enums.PerfilReportante; import mx.com.mesaregia.logistica.mapper.LogisticaMapper; import mx.com.mesaregia.logistica.repository.AsignacionLogisticaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class AsignacionLogisticaQueryServiceImpl implements AsignacionLogisticaQueryService {private final AsignacionLogisticaRepository repo;private final LogisticaMapper map;public AsignacionLogisticaQueryServiceImpl(AsignacionLogisticaRepository r,LogisticaMapper m){repo=r;map=m;} @Transactional(readOnly=true) public List<MisOperacionResponse> misOperaciones(Long u,PerfilReportante p){return repo.misOperaciones(u,p.name(),mx.com.mesaregia.logistica.domain.enums.EstadoAsignacion.CANCELADA).stream().map(map::operacion).toList();}}
